 *  extended with seconds and milliseconds only when the instant has them, so a
 *  whole-minute range looks as it always did and a precise one stays precise. */
function toLocalInput(date: Date): string {
  const pad = (n: number, width = 2) => String(n).padStart(width, "0");
  let time = `${pad(date.getHours())}:${pad(date.getMinutes())}`;
  if (date.getSeconds() || date.getMilliseconds()) {
    time += `:${pad(date.getSeconds())}`;
    if (date.getMilliseconds()) time += `.${pad(date.getMilliseconds(), 3)}`;
  }
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${time}`;
}

/** The input step that lets a datetime-local hold its value's precision (the
 *  default is 60 seconds); undefined keeps the minute picker for minute values. */
function inputStep(value: string): number | undefined {
  const seconds = value.split("T")[1]?.split(":")[2];
  if (seconds === undefined) return undefined;
  return seconds.includes(".") ? 0.001 : 1;
}

/** A datetime-local value (local wall time) → an ISO instant, or "" if blank. */
function fromLocalInput(value: string): string {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : date.toISOString();
}

/** A secondary Badge carrying an inline dismiss button: an applied log filter,
 *  an instance selection, a composer mention.
 *
 *  The chip never outgrows its row (w4/324: a discovered instance id made a
 *  406px chip in a 358px phone row, with its remove button off screen). Its
 *  text shrinks and ellipsizes; the full value stays in the DOM for assistive
 *  technology and in a tooltip, and the remove button keeps its size. */
export function RemovableChip({
  icon,
  children,
  removeLabel,
  onRemove,
  className,
}: RemovableChipProps) {
  const text = Children.toArray(children)
    .filter((child) => typeof child === "string" || typeof child === "number")
    .join("");
  return (
    <Badge
      variant="secondary"
      className={cn("max-w-full min-w-0 gap-1 pr-1", className)}
    >
      {icon}
      <span className="min-w-0 truncate" title={text || undefined}>
        {children}
      </span>
      <button
        type="button"
        aria-label={removeLabel}
        onClick={onRemove}
        className="hover:bg-muted-foreground/20 shrink-0 rounded-full p-0.5"
      >
        <X className="size-3" />
      </button>
    </Badge>
  );
}

